key.query:
query GetPostBySlug($slug: String!) {
  postBy(slug: $slug) {
    databaseId
    slug
    date
    modified
    title(format: RENDERED)
    excerpt(format: RENDERED)
    content(format: RENDERED)
    categories {
      nodes {
        databaseId
        name
        slug
        __typename
      }
      __typename
    }
    featuredImage {
      node {
        sourceUrl
        mediaDetails {
          sizes {
            name
            sourceUrl
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
